module float_multi (
    input clk,
    input rst,
    input [31:0] a,
    input [31:0] b,
    output reg [31:0] z
);

    reg [2:0] counter;
    reg [23:0] a_mantissa, b_mantissa, z_mantissa;
    reg [9:0] a_exponent, b_exponent, z_exponent;
    reg a_sign, b_sign, z_sign;
    reg [49:0] product;
    reg guard_bit, round_bit, sticky;

    parameter IDLE = 3'b000, EXTRACT = 3'b001, SPECIAL_CASES = 3'b010, MULTIPLY = 3'b011, ROUND_ADJUST = 3'b100, OUTPUT = 3'b101;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            counter <= IDLE;
            a_mantissa <= 24'd0;
            b_mantissa <= 24'd0;
            z_mantissa <= 24'd0;
            a_exponent <= 10'd0;
            b_exponent <= 10'd0;
            z_exponent <= 10'd0;
            a_sign <= 1'b0;
            b_sign <= 1'b0;
            z_sign <= 1'b0;
            product <= 50'd0;
            guard_bit <= 1'b0;
            round_bit <= 1'b0;
            sticky <= 1'b0;
            z <= 32'd0;
        end else begin
            case (counter)
                IDLE: begin
                    counter <= EXTRACT;
                end
                EXTRACT: begin
                    a_mantissa <= {a[22:0], 1'b1};
                    a_exponent <= a[30:23];
                    a_sign <= a[31];
                    b_mantissa <= {b[22:0], 1'b1};
                    b_exponent <= b[30:23];
                    b_sign <= b[31];
                    counter <= SPECIAL_CASES;
                end
                SPECIAL_CASES: begin

                    counter <= MULTIPLY;
                end
                MULTIPLY: begin
                    product <= $signed(a_mantissa) * $signed(b_mantissa);
                    z_exponent <= a_exponent + b_exponent - 127;
                    z_sign <= a_sign ^ b_sign;
                    counter <= ROUND_ADJUST;
                end
                ROUND_ADJUST: begin

                    counter <= OUTPUT;
                end
                OUTPUT: begin
                    z <= {z_sign, z_exponent, z_mantissa};
                    counter <= IDLE;
                end
                default: begin
                    counter <= IDLE;
                end
            endcase
        end
    end

endmodule
